import { test, expect } from '@playwright/test';

test.describe('Search Suggestions Highlighting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
  });

  test('should highlight matching text in search suggestions when typing', async ({ page }) => {
    // Find and click the search input field
    const searchInput = page.getByRole('searchbox');
    await searchInput.click();

    // Type a search term
    await searchInput.fill('play');

    // Wait for suggestions to appear
    await page.waitForSelector('[role="listbox"]', { timeout: 5000 });

    // Get all suggestion items
    const suggestions = page.getByRole('option');
    const suggestionCount = await suggestions.count();

    // Verify at least one suggestion appears
    expect(suggestionCount).toBeGreaterThan(0);

    // Check that the matching part is highlighted in suggestions
    const firstSuggestion = suggestions.first();
    const suggestionText = await firstSuggestion.textContent();

    // Verify the suggestion contains the search term
    expect(suggestionText?.toLowerCase()).toContain('play');

    // Check for highlight styling (mark or strong tag, or specific class)
    const highlightedText = firstSuggestion.locator('mark, strong, [class*="highlight"]');
    const highlightCount = await highlightedText.count();

    // At least one highlight element should exist
    expect(highlightCount).toBeGreaterThanOrEqual(1);
  });

  test('should highlight partial matches in search suggestions', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');
    await searchInput.click();

    // Type a partial search term
    await searchInput.fill('test');

    // Wait for suggestions dropdown
    await page.waitForSelector('[role="listbox"]', { timeout: 5000 });

    // Get suggestion items
    const suggestions = page.getByRole('option');

    // Iterate through suggestions to verify highlighting
    const suggestionCount = await suggestions.count();
    expect(suggestionCount).toBeGreaterThan(0);

    for (let i = 0; i < Math.min(suggestionCount, 3); i++) {
      const suggestion = suggestions.nth(i);
      const suggestionText = await suggestion.textContent();

      // Verify the search term appears in the suggestion
      if (suggestionText?.toLowerCase().includes('test')) {
        // Check for highlight element
        const highlight = suggestion.locator('mark, strong, [class*="highlight"]');
        const isVisible = await highlight.isVisible().catch(() => false);

        // If highlight element exists, verify it contains the matching text
        if (isVisible) {
          const highlightText = await highlight.textContent();
          expect(highlightText?.toLowerCase()).toContain('test');
        }
      }
    }
  });

  test('should update highlighting when search term changes', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');
    await searchInput.click();

    // First search
    await searchInput.fill('auto');
    await page.waitForSelector('[role="listbox"]', { timeout: 5000 });

    let suggestions = page.getByRole('option');
    let firstSuggestionText = await suggestions.first().textContent();
    expect(firstSuggestionText?.toLowerCase()).toContain('auto');

    // Clear and search for different term
    await searchInput.clear();
    await searchInput.fill('mat');
    await page.waitForSelector('[role="listbox"]', { timeout: 5000 });

    suggestions = page.getByRole('option');
    firstSuggestionText = await suggestions.first().textContent();
    expect(firstSuggestionText?.toLowerCase()).toContain('mat');

    // Verify highlighting is updated
    const highlight = suggestions.first().locator('mark, strong, [class*="highlight"]');
    const highlightText = await highlight.textContent();
    expect(highlightText?.toLowerCase()).toContain('mat');
  });

  test('should handle case-insensitive highlighting in suggestions', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');
    await searchInput.click();

    // Search with mixed case
    await searchInput.fill('PlAy');
    await page.waitForSelector('[role="listbox"]', { timeout: 5000 });

    const suggestions = page.getByRole('option');
    const firstSuggestion = suggestions.first();
    const suggestionText = await firstSuggestion.textContent();

    // Verify suggestion contains the term (case-insensitive)
    expect(suggestionText?.toLowerCase()).toContain('play');

    // Verify highlighting exists
    const highlight = firstSuggestion.locator('mark, strong, [class*="highlight"]');
    const highlightCount = await highlight.count();
    expect(highlightCount).toBeGreaterThanOrEqual(1);
  });

  test('should not highlight when search input is empty', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');
    await searchInput.click();

    // Leave search empty
    await searchInput.fill('');

    // Check if suggestions appear
    const listbox = page.locator('[role="listbox"]');
    const isVisible = await listbox.isVisible().catch(() => false);

    if (isVisible) {
      // If suggestions appear, verify no highlights are shown
      const highlights = page.locator('mark, strong, [class*="highlight"]');
      const highlightCount = await highlights.count();

      // Should have minimal or no highlights when search is empty
      expect(highlightCount).toBeLessThanOrEqual(0);
    }
  });
});
